export type SsoMode = 'proxy' | 'oidc';

export interface ProxyConfig {
  basePath?: string;
}

export interface OidcConfig {
  authority: string;
  clientId: string;
  redirectUri?: string;
  postLogoutRedirectUri?: string;
  scope?: string;
  silentRedirectUri?: string;
}

export interface SsoConfig {
  mode: SsoMode;
  proxy?: ProxyConfig;
  oidc?: OidcConfig;
  rolesClientId?: string;
}

export function resolveProxyBasePath(config: SsoConfig): string {
  return config.proxy?.basePath ?? '/oauth2';
}

export function resolveRolesClientId(config: SsoConfig): string {
  return config.rolesClientId ?? 'service-client';
}
