import { type ReactNode, useEffect, useRef } from 'react';

import { useSso } from '../useSso';

export interface RequireAuthProps {
  children: ReactNode;
  /** Shown while loading, on error, or while the login redirect is in flight. */
  fallback?: ReactNode;
}

export function RequireAuth({ children, fallback = null }: RequireAuthProps) {
  const { status, login } = useSso();
  const fired = useRef(false);

  useEffect(() => {
    if (status === 'unauthenticated' && !fired.current) {
      fired.current = true;
      login();
    }
  }, [status, login]);

  if (status === 'authenticated') return <>{children}</>;
  return <>{fallback}</>;
}
