import { type ReactNode } from 'react';

import { useSso } from '../useSso';
import { RequireAuth } from './RequireAuth';

export interface RequireRolesProps {
  roles: string[];
  children: ReactNode;
  matchAll?: boolean;
  fallback?: ReactNode;
  forbidden?: ReactNode;
}

export function RequireRoles({ roles, children, matchAll = false, fallback, forbidden = null }: RequireRolesProps) {
  const { principal } = useSso();
  const have = new Set(principal?.roles ?? []);
  const ok = matchAll ? roles.every((r) => have.has(r)) : roles.some((r) => have.has(r));
  return (
    <RequireAuth fallback={fallback}>
      {ok ? <>{children}</> : <>{forbidden}</>}
    </RequireAuth>
  );
}
