export interface Principal {
  sub: string | null;
  username: string | null;
  email: string | null;
  name: string | null;
  groups: string[];
  roles: string[];
  source: 'proxy' | 'oidc';
  raw: Record<string, unknown>;
}

export interface ProxyUserinfo {
  user?: string;
  email?: string;
  preferredUsername?: string;
  groups?: string[];
}

type Claims = Record<string, unknown>;

function strList(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((v): v is string => typeof v === 'string') : [];
}

export function rolesFromClaims(claims: Claims, clientId: string): string[] {
  const roles: string[] = [];
  const realm = claims['realm_access'];
  if (realm && typeof realm === 'object') {
    roles.push(...strList((realm as Record<string, unknown>)['roles']));
  }
  const resource = claims['resource_access'];
  if (resource && typeof resource === 'object') {
    const client = (resource as Record<string, unknown>)[clientId];
    if (client && typeof client === 'object') {
      roles.push(...strList((client as Record<string, unknown>)['roles']));
    }
  }
  return roles;
}

export function principalFromClaims(claims: Claims, clientId: string): Principal {
  return {
    sub: (claims['sub'] as string) ?? null,
    username: (claims['preferred_username'] as string) ?? null,
    email: (claims['email'] as string) ?? null,
    name: (claims['name'] as string) ?? null,
    groups: strList(claims['groups']),
    roles: rolesFromClaims(claims, clientId),
    source: 'oidc',
    raw: claims,
  };
}

export function principalFromUserinfo(info: ProxyUserinfo): Principal {
  return {
    sub: info.user ?? null,
    username: info.preferredUsername ?? info.user ?? null,
    email: info.email ?? null,
    name: null,
    groups: strList(info.groups),
    roles: [],
    source: 'proxy',
    raw: info as Record<string, unknown>,
  };
}
