import { type ReactNode } from 'react';

import { useSso } from '../useSso';

export interface LoginButtonProps {
  children?: ReactNode;
  returnTo?: string;
  className?: string;
}

export function LoginButton({ children = 'Войти', returnTo, className }: LoginButtonProps) {
  const { login } = useSso();
  return (
    <button type="button" className={className} onClick={() => login(returnTo)}>
      {children}
    </button>
  );
}
