import { type ReactNode } from 'react';

import { useSso } from '../useSso';
import { RequireAuth } from './RequireAuth';

export interface RequireGroupsProps {
  groups: string[];
  children: ReactNode;
  matchAll?: boolean;
  fallback?: ReactNode;
  forbidden?: ReactNode;
}

export function RequireGroups({ groups, children, matchAll = false, fallback, forbidden = null }: RequireGroupsProps) {
  const { principal } = useSso();
  const have = new Set(principal?.groups ?? []);
  const ok = matchAll ? groups.every((g) => have.has(g)) : groups.some((g) => have.has(g));
  return (
    <RequireAuth fallback={fallback}>
      {ok ? <>{children}</> : <>{forbidden}</>}
    </RequireAuth>
  );
}
