export interface AuthHttpOptions {
  getAccessToken: () => Promise<string | null>;
  /** Called when a response is 401 (e.g. pass SsoProvider's login). */
  onUnauthorized?: () => void;
}

export interface AuthFetchOptions extends AuthHttpOptions {
  fetchImpl?: typeof fetch;
}

/** Only same-origin/relative requests get the bearer token (prevents leaking it to third-party URLs). */
function isSameOrigin(input: RequestInfo | URL): boolean {
  try {
    const href =
      typeof input === 'string'
        ? input
        : input instanceof URL
          ? input.href
          : (input as Request).url;
    return new URL(href, window.location.origin).origin === window.location.origin;
  } catch {
    return true; // relative/opaque → treat as same-origin
  }
}

export function createAuthFetch(options: AuthFetchOptions): typeof fetch {
  const impl = options.fetchImpl ?? fetch;
  return (async (input: RequestInfo | URL, init: RequestInit = {}) => {
    const headers = new Headers(init.headers);
    const token = await options.getAccessToken();
    if (token && isSameOrigin(input)) headers.set('Authorization', `Bearer ${token}`);
    const res = await impl(input, { ...init, headers, credentials: init.credentials ?? 'include' });
    if (res.status === 401) options.onUnauthorized?.();
    return res;
  }) as typeof fetch;
}

type AxiosHeadersLike = Record<string, string> & { set?: (name: string, value: string) => void };

interface AxiosLike {
  interceptors: {
    request: { use: (fn: (config: { headers?: AxiosHeadersLike }) => unknown) => unknown };
    response: {
      use: (onFulfilled: (r: unknown) => unknown, onRejected: (e: unknown) => unknown) => unknown;
    };
  };
}

export function attachAxios(instance: AxiosLike, options: AuthHttpOptions): void {
  instance.interceptors.request.use(async (config) => {
    const token = await options.getAccessToken();
    if (token) {
      const headers = config.headers;
      if (headers && typeof headers.set === 'function') {
        headers.set('Authorization', `Bearer ${token}`);
      } else {
        config.headers = config.headers ?? {};
        config.headers.Authorization = `Bearer ${token}`;
      }
    }
    return config;
  });
  instance.interceptors.response.use(
    (response) => response,
    (error) => {
      const status = (error as { response?: { status?: number } })?.response?.status;
      if (status === 401) options.onUnauthorized?.();
      return Promise.reject(error);
    },
  );
}
