import { type ReactNode } from 'react';

import { useSso } from '../useSso';
import { Spinner } from './Spinner';

export interface SsoGateProps {
  children: ReactNode;
  /** Shown while bootstrapping. Defaults to <Spinner/>. */
  loading?: ReactNode;
  /** Shown when unauthenticated. Defaults to null. */
  fallback?: ReactNode;
}

export function SsoGate({ children, loading = <Spinner />, fallback = null }: SsoGateProps) {
  const { status } = useSso();
  if (status === 'loading') return <>{loading}</>;
  if (status === 'authenticated') return <>{children}</>;
  return <>{fallback}</>;
}
