import { UserManager, WebStorageStateStore } from 'oidc-client-ts';

import { resolveRolesClientId, type SsoConfig } from '../config';
import { principalFromClaims, type Principal } from '../Principal';
import type { SessionProvider } from './types';

/** Accept only same-origin relative paths ("/x"); reject protocol-relative ("//host") and absolute URLs (open-redirect guard). */
function safeReturnTo(value: string | null): string | null {
  if (!value) return null;
  if (!value.startsWith('/') || value.startsWith('//')) return null;
  return value;
}

export function createOidcProvider(config: SsoConfig): SessionProvider {
  const o = config.oidc;
  if (!o) throw new Error('@dada/react-sso: oidc mode requires config.oidc');
  const rolesClient = resolveRolesClientId(config);
  const redirectUri = o.redirectUri ?? `${window.location.origin}/callback`;

  const userManager = new UserManager({
    authority: o.authority,
    client_id: o.clientId,
    redirect_uri: redirectUri,
    post_logout_redirect_uri: o.postLogoutRedirectUri ?? window.location.origin,
    response_type: 'code',
    scope: o.scope ?? 'openid profile email',
    automaticSilentRenew: true,
    silent_redirect_uri: o.silentRedirectUri,
    userStore: new WebStorageStateStore({ store: window.localStorage }),
  });

  return {
    async load(): Promise<Principal | null> {
      const search = window.location.search;
      if (search.includes('code=') || search.includes('error=')) {
        try {
          const user = await userManager.signinRedirectCallback();
          const state = typeof user?.state === 'string' ? user.state : null;
          const fallbackPath = new URL(redirectUri, window.location.origin).pathname;
          window.history.replaceState({}, document.title, safeReturnTo(state) ?? fallbackPath);
          return user ? principalFromClaims(user.profile as Record<string, unknown>, rolesClient) : null;
        } catch {
          // fall through to getUser
        }
      }
      const user = await userManager.getUser();
      if (!user || user.expired) return null;
      return principalFromClaims(user.profile as Record<string, unknown>, rolesClient);
    },
    async login(returnTo?: string): Promise<void> {
      await userManager.signinRedirect(returnTo ? { state: returnTo } : undefined);
    },
    async logout(): Promise<void> {
      await userManager.signoutRedirect();
    },
    async getAccessToken(): Promise<string | null> {
      const user = await userManager.getUser();
      return user && !user.expired ? user.access_token : null;
    },
    onExpired(cb: () => void): () => void {
      userManager.events.addAccessTokenExpired(cb);
      return () => userManager.events.removeAccessTokenExpired(cb);
    },
  };
}
