import type { SsoConfig } from '../config';
import { createOidcProvider } from './oidcProvider';
import { createProxyProvider } from './proxyProvider';
import type { SessionProvider } from './types';

export function createProvider(config: SsoConfig): SessionProvider {
  return config.mode === 'oidc' ? createOidcProvider(config) : createProxyProvider(config);
}
