import { useSso } from '../useSso';

export interface UserMenuProps {
  className?: string;
  logoutLabel?: string;
}

export function UserMenu({ className, logoutLabel = 'Выйти' }: UserMenuProps) {
  const { status, principal, logout } = useSso();
  if (status !== 'authenticated' || !principal) return null;
  return (
    <div data-dada-sso-usermenu className={className}>
      <span data-dada-sso-username>{principal.username ?? principal.email ?? principal.sub}</span>
      <button type="button" onClick={() => logout()}>
        {logoutLabel}
      </button>
    </div>
  );
}
