import { type ReactNode, useCallback, useEffect, useMemo, useRef, useState } from 'react';

import type { SsoConfig } from './config';
import type { Principal } from './Principal';
import { createProvider } from './providers/factory';
import type { SessionProvider } from './providers/types';
import { SsoContext, type SsoStatus } from './SsoContext';

export interface SsoProviderProps {
  config: SsoConfig;
  children: ReactNode;
  /** Inject a provider (tests / custom). Defaults to createProvider(config). */
  provider?: SessionProvider;
}

export function SsoProvider({ config, children, provider }: SsoProviderProps) {
  const providerRef = useRef<SessionProvider | null>(null);
  if (providerRef.current === null) {
    providerRef.current = provider ?? createProvider(config);
  }
  const [status, setStatus] = useState<SsoStatus>('loading');
  const [principal, setPrincipal] = useState<Principal | null>(null);

  const reload = useCallback(async () => {
    try {
      const p = await providerRef.current!.load();
      setPrincipal(p);
      setStatus(p ? 'authenticated' : 'unauthenticated');
    } catch {
      setPrincipal(null);
      setStatus('error');
    }
  }, []);

  useEffect(() => {
    let active = true;
    providerRef.current!
      .load()
      .then((p) => {
        if (!active) return;
        setPrincipal(p);
        setStatus(p ? 'authenticated' : 'unauthenticated');
      })
      .catch(() => {
        if (active) {
          setPrincipal(null);
          setStatus('error');
        }
      });
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    const off = providerRef.current!.onExpired?.(() => {
      setPrincipal(null);
      setStatus('unauthenticated');
    });
    return off;
  }, []);

  const value = useMemo(
    () => ({
      status,
      principal,
      login: (returnTo?: string) => void providerRef.current!.login(returnTo),
      logout: (returnTo?: string) => void providerRef.current!.logout(returnTo),
      reload,
      getAccessToken: () => providerRef.current!.getAccessToken(),
      hasGroup: (group: string) => principal?.groups.includes(group) ?? false,
      hasRole: (role: string) => principal?.roles.includes(role) ?? false,
    }),
    [status, principal, reload],
  );

  return <SsoContext.Provider value={value}>{children}</SsoContext.Provider>;
}
